# denue_escuelas.map - CAPAS GEOMETRICAS BASE (mxsigvector)
#======================================================================
# GENERADO AUTOMÁTICAMENTE A PARTIR DE: scripts/layers/denue/01_escuelas.py
# Descripción: Escuelas primarias en el estado de Veracruz
# Modo de Operación: MULTIPLES_CAPAS
#======================================================================

LAYER
  NAME "c_denue_escuelas_primarias"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom FROM denue.escuelas_primarias) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Escuelas primarias"
    "wms_enable_request" "*"
  END
  CLASS
    NAME "Escuelas primarias"
    STYLE
      COLOR 11 123 234
      SYMBOL 'circulor'
      SIZE 9
      OUTLINECOLOR 0 0 0
    END
  END
END

